I did not add `aap:caps/state-rw@0.1.0`. The node's `with` clause is its entire authority, and this node is granted only the HTTP client, notifier, and wall clock. Granting it state access requires a change to the graph's `with` clause, not to the node body. The world below imports only the three granted interfaces.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();
        let seconds = now.seconds;

        // A transport failure is a value, not a trap: report zero characters
        // and carry on. A request outside the allowlist still traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars from {feed_url}");
        let accepted = notifier::notify(&message);

        // The contract requires `notified == true` on every output. A refused
        // notification cannot be reported as a success, so the node traps instead.
        assert!(accepted, "notifier refused the heartbeat message");

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

